def _ab(t):
    f = lambda x: (math.sin(math.pi*x/3) - t) * (math.cos(math.pi*x/3) - t)
    xs = [k*0.0005 for k in range(0, 12000)]
    roots = []
    for x1, x2 in zip(xs, xs[1:]):
        g1, g2 = f(x1), f(x2)
        if g1*g2 < 0:
            roots.append(bis(f, x1, x2))
    return min(roots), max(roots)

def standard():
    sums = []
    for t in (-0.95, -0.8, -0.6, -0.5, -0.3, -0.1, -0.01):
        a, b = _ab(t)
        sums.append(a + b)
    assert max(sums) - min(sums) < 1e-6
    fr = Fraction(sums[0]).limit_denominator(100)
    return fr.numerator + fr.denominator

def unique():
    return [standard()]
